def lookup(assembly: str, namespace: str, class_name: str) -> tuple[bytes, bytes] | None:
    for candidate in (assembly, f'{assembly}.dll', assembly.removesuffix('.dll')):
        found = GAME_SCRIPT_HASHES.get((candidate, namespace, class_name))
        if found is not None:
            return found
    return None

