def lookup_properties(assembly: str, namespace: str, class_name: str) -> bytes | None:
    for candidate in (assembly, f'{assembly}.dll', assembly.removesuffix('.dll')):
        found = MONOSCRIPT_PROPERTIES_HASHES.get((candidate, namespace, class_name))
        if found is not None:
            return found
    return None

