def lookup_path_id(assembly: str, namespace: str, class_name: str) -> int | None:
    for candidate in (assembly, f'{assembly}.dll', assembly.removesuffix('.dll')):
        found = SCRIPT_PATH_IDS.get((candidate, namespace, class_name))
        if found is not None:
            return found
    return None
